recipe('air-fryer-chimichangas','Crisp beef and bean chimichangas',M,4,180,20,22,[(400,'beef'),(300,'tomato'),(200,'beans','','canned'),(100,'corn','','canned'),(10,'garlic','Grated'),(4,'cumin'),(2,'paprika'),(320,'tortilla','Eight 40 g wraps'),(100,'cheddar','Grated'),(25,'egg','Beaten')],['Cook beef with tomatoes and garlic in a shallow approved dish at 180°C for 10 minutes, stirring twice. Add beans, corn and spices and cook another 4 minutes until beef reaches 71°C. Let filling cool for 5 minutes.','Divide filling and cheddar between eight wraps. Fold in both sides, then roll firmly to enclose. Brush with beaten egg.','Air fry seam-side down at 200°C for 6–8 minutes until crisp and 75°C in the centre. Cook in batches, adding time for each basket.'],'Beef, kidney beans and sweetcorn fill tightly folded tortillas that crisp without deep frying.',wait=5,internal=75,allergens=['wheat','gluten','milk','egg'],equipment=['Shallow air-fryer-safe dish'])
recipe('air-fryer-pizza-fries','Chorizo and mozzarella loaded chips',Q,2,180,15,30,[(500,'potato','Cut into 1 cm chips'),(10,'oil'),(2,'oregano'),(80,'mozz','Grated'),[60,'chorizo','F008126','Thinly sliced']],[ 'Toss chips with oil and oregano. Air fry at 180°C for 22–25 minutes, shaking every 7 minutes, until tender and lightly crisp.','Scatter chorizo over the chips and cook for 3 minutes. Add mozzarella and cook another 2 minutes until melted and the chorizo is thoroughly hot.','Check a thick chorizo slice reaches 71°C and serve straight away.'],'Crisp potato chips become a sharing meal with smoky chorizo and melted mozzarella.',internal=71,allergens=['milk','sulphites'],nutritionNote='Source potato and chorizo counts converted into measured portions. No optional dipping sauce counted.')
recipe('how-to-make-the-best-ever-juicy-lucy-cheese-burger-in-the-airfryer','Cheese-filled beef patties',M,4,180,20,18,[(600,'beef'),(60,'onion','Very finely diced'),(5,'garlic','Grated'),(2,'thyme'),(2,'oregano'),(60,'cheddar','Cut into four pieces'),(40,'creamcheese')],['Mix beef, onion, garlic and herbs. Make eight thin discs. Put a piece of cheddar and a quarter of cream cheese in the centre of four discs.','Cover with remaining discs and press the edges firmly together, fully enclosing the cheese. Keep the finished patties about 2 cm thick.','Air fry at 180°C for 15–18 minutes, turning carefully halfway. Probe the meat around the filling for 71°C. Rest for 3 minutes because the enclosed cheese will be very hot.'],'Sealed beef patties hide a molten cheddar and cream-cheese centre.',wait=3,allergens=['milk'],nutritionNote='Nutrition covers filled patties only; bread and burger sauces excluded.')
recipe('the-ultimate-fried-english-breakfast-in-the-air-fryer','Air-fryer breakfast plate',Q,2,180,10,20,[(200,'sausage','Four small beef sausages'),(80,'bacon'),(200,'freshTomato','Halved'),(200,'bakedbeans','','canned'),(100,'egg','Beaten'),(20,'milk'),(5,'butter')],['Air fry sausages at 180°C for 5 minutes. Turn them, add bacon and tomato halves, and cook for another 8–10 minutes until sausages reach 71°C. Keep covered and hot.','Mix eggs, milk and butter in a greased approved ramekin. Put beans in a second ramekin. Air fry at 160°C for 6–8 minutes, stirring eggs after 3 minutes.','Stop when eggs are set and 75°C, and beans are steaming hot. Divide everything between two plates.'],'Sausages, bacon and roasted tomato share a plate with creamy eggs and hot baked beans.',internal=75,allergens=['egg','milk','wheat','gluten','sulphites'],equipment=['Two air-fryer-safe ramekins'],nutritionNote='Black pudding omitted; sausages and bacon reduced to practical measured servings. Cook time reflects sequential use of a large single basket.')
recipe('air-fryer-breakfast-casserole','Sweet potato and sausage egg bake',Q,4,180,15,35,[(240,'sausage','Slice into 1 cm rounds'),(300,'sweetpotato','Dice to 1 cm'),(200,'capsicum','Dice'),(10,'oil'),(200,'egg','Beaten'),(80,'yoghurt'),(80,'cheddar','Grated'),(50,'mozz','Grated'),(2,'oregano')],['Toss sweet potato and capsicum with oil and oregano. Air fry at 180°C for 8 minutes. Add sausage slices and cook 8 minutes more, stirring once, until sausages reach 71°C.','Beat eggs with yoghurt and cheeses. Put cooked filling into a shallow approved dish, then pour over the egg mixture. Keep mixture no deeper than 4 cm.','Air fry at 160°C for 16–19 minutes until just set and 75°C in the centre. Rest for 3 minutes before cutting into four.'],'Sweet potato cubes and sausage pieces make this cheese-topped egg bake a filling breakfast or supper.',wait=3,internal=75,allergens=['egg','milk','wheat','gluten','sulphites'],equipment=['Shallow air-fryer-safe baking dish'],nutritionNote='Measured reduced cheese replaces four source cups of cheese; yoghurt replaces sour cream. All macros recalculated.')
recipe('air-fryer-shrimp-tacos','Prawn tacos with avocado slaw',S,2,180,20,10,[(300,'prawn','Thawed and patted dry'),(160,'tortilla','Four 40 g tortillas'),(100,'avocado'),(100,'cabbage','Shredded'),(40,'onion','Finely diced'),(60,'yoghurt'),(20,'lemon'),(5,'garlic','Grated'),(2,'cumin'),(2,'paprika'),(5,'oil')],['Mix half the avocado with yoghurt, lemon and garlic to make a rough cream. Slice the remaining avocado and toss cabbage with onion.','Coat prawns with oil, cumin and paprika. Air fry in one layer at 180°C for 7–10 minutes, turning halfway, until the thickest prawn reaches 63°C.','Warm tortillas according to their packet. Divide avocado cream, slaw, prawns and sliced avocado among them.'],'Warm spiced prawns contrast with cold cabbage slaw and a thick avocado-yoghurt sauce.',internal=63,allergens=['crustacean','milk','wheat','gluten'],nutritionNote='Raw prawns replace the source precooked frozen prawns; included tortilla weights resolve a missing source ingredient. Lemon replaces lime using a measured juice reference.')
recipe('airfryer-beef-wellington','Individual beef and mushroom Wellingtons',M,2,180,30,40,[[300,'lean beef fillet','F000836','Two 150 g pieces, no thicker than 3 cm'],(200,'mushroom','Finely chopped'),(5,'garlic','Grated'),(5,'oil'),(10,'butter'),(180,'puff','Thawed; two equal pieces'),(25,'egg','Beaten'),(2,'thyme')],['Air fry mushrooms, garlic, butter and thyme in a shallow dish at 180°C for 10 minutes, stirring twice, until liquid evaporates. Transfer to a plate to cool.','Brush beef with oil and air fry at 180°C for 6 minutes, turning halfway. Cool for 10 minutes, then pat dry.','Divide mushrooms over the pastry centres, place beef on top and fold pastry around each piece. Seal edges with egg, place seam-side down and brush tops with remaining egg. Cut small vents.','Air fry at 180°C for 20–24 minutes until pastry is cooked underneath and the beef centre reaches 71°C. Rest 5 minutes before slicing.'],'Two pastry parcels enclose beef fillet and a dry garlic-mushroom filling.',wait=15,allergens=['wheat','gluten','egg','milk'],difficulty='Moderate',equipment=['Shallow air-fryer-safe dish'],nutritionNote='Individual portions replace the 1 kg joint; pâté omitted. Beef is cooked and wrapped on the same day, avoiding the source partial-cook overnight storage method.')
recipe('stromboli-in-air-fryer','Ham and mozzarella pizza roll',Q,4,160,20,25,[[300,'ready-to-roll pizza dough','F001653','Commercial pizza base used as declared nutrient proxy'],(200,'ham','Finely chopped','cooked'),(120,'mozz','Grated'),(80,'tomato','Crush and drain excess juice','canned'),(20,'paste'),(25,'egg','Beaten'),(2,'oregano')],['Roll pizza dough into a rectangle about 5 mm thick. Spread with tomato paste and drained tomato, leaving a 2 cm border, then add ham, mozzarella and oregano.','Roll from a long edge into a compact log that fits the basket. Seal ends and seam firmly, cut three small vents and brush with egg.','Place seam-side down and air fry at 160°C for 20–25 minutes. Check the centre reaches 75°C and the inner dough is fully baked, adding 3-minute intervals if needed. Rest for 5 minutes before cutting four portions.'],'A spiral of ham, tomato and mozzarella runs through this sliceable pizza-dough roll.',wait=5,internal=75,allergens=['wheat','gluten','milk','egg'],nutritionNote='AFCD commercial pizza base is a declared proxy for ready-to-roll dough; actual brands vary. Defined 300 g dough replaces the source unspecified bread-machine batch.')
recipe('duck-legs-in-air-fryer','Sticky garlic duck legs',C,2,180,15,40,[[360,'duck leg meat and skin','F003634','Edible weight excluding bones, from two small legs'],(20,'honey'),(20,'soy'),(15,'vinegar'),(10,'garlic','Grated'),(5,'ginger','Grated'),(1,'chilli')],['Pat duck legs dry. Score the skin shallowly without cutting into the meat. Mix the remaining ingredients and reserve a clean third of the glaze.','Arrange legs skin-side up and air fry at 180°C for 20 minutes. Turn, brush with some unreserved glaze and cook for another 10 minutes.','Turn skin-side up, brush again and cook 5–10 minutes longer until the thick meat beside the bone reaches 74°C. Rest 5 minutes, then brush with the clean reserved glaze.'],'Duck legs roast until their skin browns, then take on a sticky garlic, ginger and chilli glaze.',wait=5,internal=74,allergens=['soy','wheat','gluten'],nutritionNote='Edible duck weight excludes bones; purchase weight will be higher. A measured homemade glaze replaces sweet chilli sauce; source 18-minute timing extended to allow a poultry thermometer target.')
